<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import L from 'leaflet'
import {mapTiles} from '../services/map-tiles'
import 'leaflet/dist/leaflet.css'
import '../radio-map.css'
import {api} from '../services/api'
type Point={at:string;trip?:string;gps:{at:string;lat:number;lon:number;accuracyM?:number;hdop?:number};value:number|null;state:string;color:string;carrier?:string;band?:string;source:string;accuracyUnknown:boolean}
type Cell={bounds:[[number,number],[number,number]];color:string;median:number;sample_count:number;distinct_trip_count:number;low_confidence:boolean}
type History={tripWeighted?:boolean;tripCountKnown?:boolean;unit:string;points:Point[];cells:Cell[];total:number;unplaced:number;accuracyExcluded:number;missing:number;outOfService:number;carriers:string[];bands:string[];truncated:boolean;reason?:string}
type Legend={unit:string;note:string;thresholds:{minimum:number|null;label:string;color:string}[]}
const container=ref<HTMLElement>(),metric=ref('rsrp'),mode=ref('route'),days=ref('7'),carrier=ref(''),band=ref(''),size=ref('50'),unknown=ref(false),online=ref(true)
const tileFailed=ref(false)
const legend=ref<Legend>(),result=ref<History>(),loading=ref(false),error=ref(''),selected=ref<Point>()
let map:L.Map|undefined,layers:L.LayerGroup|undefined,tiles:L.TileLayer|undefined,resize:ResizeObserver|undefined,sequence=0,fitted=false
const empty=computed(()=>mode.value==='grid'?!result.value?.cells.length:!result.value?.points.length)
const fmt=(date:string)=>new Date(date).toLocaleString('ja-JP',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'})
function popup(lines:string[]){const node=document.createElement('div');for(const text of lines){const p=document.createElement('div');p.textContent=text;node.appendChild(p)}return node}
async function load(){const id=++sequence;loading.value=true;error.value='';try{const query=new URLSearchParams({days:days.value,metric:metric.value,cellSize:size.value,includeUnknownAccuracy:String(unknown.value),tripWeighted:'true'});if(carrier.value)query.set('carrier',carrier.value);if(band.value)query.set('band',band.value);const [history,scale]=await Promise.all([api<History|{data:History}>('/radio/history?'+query),api<Legend>('/radio/heatmap/legend?metric='+metric.value)]);if(id!==sequence)return;result.value='data' in history?history.data:history;legend.value=scale;selected.value=undefined;render()}catch(e){if(id===sequence){result.value=undefined;error.value=e instanceof Error?e.message:'電波履歴を取得できません';layers?.clearLayers();renderBackground()}}finally{if(id===sequence)loading.value=false}}
function render(){if(!map||!layers)return;layers.clearLayers();const data=result.value;if(!data){renderBackground();return};const bounds:L.LatLngExpression[]=[];if(mode.value==='grid'){for(const cell of data.cells){L.rectangle(cell.bounds,{color:cell.color,fillOpacity:cell.low_confidence?.3:.6,weight:1,dashArray:cell.low_confidence?'3 3':undefined}).bindPopup(popup([`中央値 ${cell.median.toFixed(1)} ${data.unit}`,`${cell.sample_count} 観測 / ${data.tripCountKnown?cell.distinct_trip_count+' 走行':'走行数不明'}`,cell.low_confidence?'観測数が少ないため参考値':''])).addTo(layers);bounds.push(...cell.bounds)}}else{let previous:Point|undefined;for(const point of data.points){const position:L.LatLngExpression=[point.gps.lat,point.gps.lon];bounds.push(position);const dt=previous?(Date.parse(point.at)-Date.parse(previous.at))/1000:Infinity;const dx=previous?(point.gps.lon-previous.gps.lon)*91000:0,dy=previous?(point.gps.lat-previous.gps.lat)*111000:0;const connected=previous&&dt>0&&dt<=5&&Math.hypot(dx,dy)/dt<=75&&previous.trip===point.trip;if(mode.value==='route'&&connected){L.polyline([[previous!.gps.lat,previous!.gps.lon],position],{color:point.color,weight:5,opacity:point.accuracyUnknown?.5:.85,dashArray:point.state==='missing'||point.state==='out-of-service'?'4 6':undefined}).addTo(layers)}const dot=L.circleMarker(position,{radius:mode.value==='points'?5:3,color:point.color,fillColor:point.color,fillOpacity:point.state==='missing'?.2:.9,weight:point.accuracyUnknown?1:2,dashArray:point.accuracyUnknown?'2 2':undefined}).bindPopup(popup([fmt(point.at),`${metric.value.toUpperCase()} ${point.value===null?'未取得':point.value+' '+data.unit}`,`${point.carrier||'回線不明'} / ${point.band||'バンド不明'}`,point.accuracyUnknown?'位置精度: 不明':`位置精度: ${point.gps.accuracyM} m`]));dot.on('click',()=>selected.value=point);dot.addTo(layers);previous=point}}if(bounds.length&&!fitted){map.fitBounds(L.latLngBounds(bounds),{padding:[28,28],maxZoom:17});fitted=true}renderBackground()}
function fit(){fitted=false;render()}
function download(format:'csv'|'geojson'){const data=result.value;if(!data?.points.length)return;let body='',type='';if(format==='geojson'){body=JSON.stringify({type:'FeatureCollection',features:data.points.map(p=>({type:'Feature',geometry:{type:'Point',coordinates:[p.gps.lon,p.gps.lat]},properties:{at:p.at,metric:metric.value,value:p.value,state:p.state,carrier:p.carrier,band:p.band,accuracyM:p.gps.accuracyM??null,source:p.source}}))},null,2);type='application/geo+json'}else{const escape=(v:unknown)=>'"'+String(v??'').replaceAll('"','""')+'"';body='\ufeff'+[['日時','緯度','経度','指標','値','状態','回線','バンド','精度m','取得元'],...data.points.map(p=>[p.at,p.gps.lat,p.gps.lon,metric.value,p.value,p.state,p.carrier,p.band,p.gps.accuracyM,p.source])].map(row=>row.map(escape).join(',')).join('\r\n');type='text/csv;charset=utf-8'}const url=URL.createObjectURL(new Blob([body],{type}));const anchor=document.createElement('a');anchor.href=url;anchor.download=`np1-radio-${new Date().toISOString().slice(0,10)}.${format}`;anchor.click();URL.revokeObjectURL(url)}
watch([metric,days,carrier,band,size,unknown],()=>{fitted=false;load()});watch(mode,render)
function renderBackground(){if(!map)return;if(online.value&&!empty.value&&!tiles){tileFailed.value=false;tiles=mapTiles(()=>tileFailed.value=true).addTo(map)}else if(!online.value||empty.value){tiles?.remove();tiles=undefined;tileFailed.value=false}}
watch(online,renderBackground)
onMounted(()=>{if(container.value){map=L.map(container.value).setView([36.2,138.2],5);map.attributionControl.setPrefix(false);layers=L.layerGroup().addTo(map);resize=new ResizeObserver(()=>map?.invalidateSize());resize.observe(container.value)}load()})
onUnmounted(()=>{sequence++;resize?.disconnect();map?.remove()})
</script>
<template>
 <div class="radio-survey">
  <div class="radio-toolbar"><label>期間<select v-model="days"><option value="7">7日間</option><option value="30">30日間</option><option value="90">90日間</option><option value="365">365日間</option></select></label><label>電波の指標<select v-model="metric"><option value="rsrp">受信強度 · RSRP</option><option value="sinr">信号品質 · SINR</option><option value="rsrq">受信品質 · RSRQ</option></select></label><label>表示<select v-model="mode"><option value="route">走行経路</option><option value="points">測定点</option><option value="grid">エリア集計</option></select></label><label v-if="mode==='grid'">区画サイズ<select v-model="size"><option value="20">20 m</option><option value="50">50 m</option><option value="100">100 m</option></select></label><button class="button secondary radio-refresh" :disabled="loading" @click="load">{{loading?'取得中…':'更新'}}</button></div>
  <details class="radio-filters"><summary>絞り込み・地図設定</summary><div class="radio-filter-content"><label>回線<select v-model="carrier"><option value="">すべての回線</option><option v-for="name in result?.carriers" :key="name">{{name}}</option></select></label><label>バンド<select v-model="band"><option value="">すべてのバンド</option><option v-for="name in result?.bands" :key="name">{{name}}</option></select></label><label class="radio-check"><input v-model="unknown" type="checkbox">精度不明の測定点も表示</label><label class="radio-check"><input v-model="online" type="checkbox">背景地図を表示</label></div><p>精度50 m超・HDOP 5超・測位時刻の差5秒超は表示しません。精度不明の点はエリア集計に含めません。</p></details>
  <div class="radio-observation-status" aria-live="polite"><span><strong>{{result?.total?.toLocaleString()??'—'}}</strong> 電波観測</span><span><strong>{{result?.points.length.toLocaleString()??'—'}}</strong> 地図表示</span><span v-if="result?.unplaced">測位不足 {{result.unplaced.toLocaleString()}}</span><span v-if="result?.accuracyExcluded">精度不明 {{result.accuracyExcluded.toLocaleString()}}</span><span v-if="result?.outOfService">圏外 {{result.outOfService.toLocaleString()}}</span><span v-if="result?.truncated">直近20,000件を表示</span></div>
  <div v-if="error" class="radio-error" role="alert">{{error}}<button class="button secondary" @click="load">再試行</button></div>
  <div class="radio-map-frame"><div ref="container" class="radio-map-canvas" aria-label="電波観測の地図"></div><div v-if="empty&&!error&&!loading" class="radio-empty"><strong>{{result?.total?'地図に表示できる測位がありません':'この期間の記録はまだありません'}}</strong><p>{{mode==='grid'&&result?.points.length?'精度が確認できる測定点だけをエリア集計に使用します。':result?.reason||'GPS測位と電波観測がそろうと、走行経路を表示します。'}}</p></div><button v-if="!empty" class="radio-fit button secondary" @click="fit">全体を表示</button></div>
  <p v-if="tileFailed" class="radio-note" role="note">背景地図を読み込めませんでした。走行経路と電波の観測点は引き続き表示します。</p>
  <div class="radio-legend"><strong>{{metric.toUpperCase()}} / {{legend?.unit}}</strong><span v-for="item in legend?.thresholds" :key="item.label"><i :style="{background:item.color}"></i>{{item.minimum===null?'下限未満':`≥ ${item.minimum}`}} {{item.label}}</span><span><i style="background:#3f4a5a"></i>圏外</span><span><i style="background:#a8afb8"></i>未取得</span></div>
  <p class="radio-note">{{mode==='grid'?(result?.tripWeighted?'各区画は走行ごとの中央値を集計。':'走行の区別が未取得のため、各区画は全観測の中央値を表示。')+'観測3件未満は薄く表示します。':'測位や電波が途切れた区間はつなぎません。'}} {{legend?.note}}</p>
  <div v-if="selected" class="radio-selected"><strong>{{fmt(selected.at)}}</strong><span>{{metric.toUpperCase()}} {{selected.value??'未取得'}} {{selected.value===null?'':result?.unit}}</span><span>{{selected.carrier||'回線不明'}} / {{selected.band||'バンド不明'}}</span><span>{{selected.accuracyUnknown?'位置精度不明':`位置精度 ${selected.gps.accuracyM} m`}}</span></div>
  <div class="radio-export"><span>表示対象の測定点を書き出す</span><button class="button secondary" :disabled="!result?.points.length" @click="download('csv')">CSV</button><button class="button secondary" :disabled="!result?.points.length" @click="download('geojson')">GeoJSON</button></div>
 </div>
</template>
